{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.original_ros_str_eoq as WITH next_inwards AS ( SELECT i1.sku_group, i1.inward_date, i1.inventory_on_inward_date, MIN(i2.inward_date) AS next_inward_date FROM snitch_db.maplemonk.inwards_date_and_quantity_eoq i1 LEFT JOIN snitch_db.maplemonk.inwards_date_and_quantity_eoq i2 ON i1.sku_group = i2.sku_group AND i2.inward_date > i1.inward_date GROUP BY 1, 2, 3 ), inv_window AS ( SELECT ni.sku_group, ni.inward_date, ni.inventory_on_inward_date, ni.next_inward_date, inv.date, inv.inv, DATEDIFF(\'day\', ni.inward_date, inv.date) AS days_since_inward FROM next_inwards ni JOIN snitch_db.maplemonk.dod_all_channels_sku_inventory inv ON ni.sku_group = inv.sku_group AND inv.date >= ni.inward_date AND (ni.next_inward_date IS NULL OR inv.date < ni.next_inward_date) ), ros_point AS ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY sku_group, inward_date ORDER BY date) AS rn, CASE WHEN inv <= inventory_on_inward_date * 0.1 THEN 1 ELSE 0 END AS hit_10pct FROM inv_window ) x WHERE hit_10pct = 1 QUALIFY ROW_NUMBER() OVER (PARTITION BY sku_group, inward_date ORDER BY date) = 1 ), inventory_day_60 AS ( SELECT iv.sku_group, iv.inward_date, iv.inventory_on_inward_date, iv.inv AS inv_on_day_60, \'YES\' AS is_60_days_complete FROM inv_window iv WHERE iv.days_since_inward = 60 UNION ALL SELECT iv.sku_group, iv.inward_date, iv.inventory_on_inward_date, iv.inv AS inv_on_day_60, \'YES\' AS is_60_days_complete FROM inv_window iv JOIN next_inwards ni ON iv.sku_group = ni.sku_group AND iv.date = DATEADD(day, -1, ni.next_inward_date) WHERE iv.days_since_inward <= 60 ), latest_inv AS ( SELECT sku_group, inward_date, MAX(date) AS latest_date, MAX(inv) AS latest_inventory, DATEDIFF(\'day\', MIN(inward_date), CURRENT_DATE) AS days_till_now FROM inv_window GROUP BY 1, 2 ), final_metrics_pre AS ( SELECT ni.sku_group, ni.inward_date, ni.inventory_on_inward_date, case when COALESCE(ros.date, li.latest_date) = current_date then COALESCE(ros.date, li.latest_date) else DATEADD(day, -2, COALESCE(ros.date, li.latest_date)) end AS ros_hit_date, COALESCE(ros.days_since_inward, li.days_till_now) AS ros_days_taken, CASE WHEN ros.date IS NOT NULL THEN \'YES\' ELSE \'NO\' END AS is_ros_hit, COALESCE(id60.is_60_days_complete, \'NO\') AS is_60_days_complete FROM next_inwards ni LEFT JOIN ros_point ros ON ni.sku_group = ros.sku_group AND ni.inward_date = ros.inward_date LEFT JOIN ( SELECT sku_group, inward_date, MAX(inv_on_day_60) AS inv_on_day_60, MAX(is_60_days_complete) AS is_60_days_complete FROM inventory_day_60 group by 1,2 ) id60 ON ni.sku_group = id60.sku_group AND ni.inward_date = id60.inward_date LEFT JOIN latest_inv li ON ni.sku_group = li.sku_group AND ni.inward_date = li.inward_date ), final_metrics as ( select a.*, b.inward_start_date from final_metrics_pre a left join snitch_db.maplemonk.inwards_date_and_quantity_eoq b on a.sku_group = b.sku_group and a.inward_date = b.inward_date ), inv_matching as ( select a.*,b.inv from final_metrics a left join snitch_db.maplemonk.dod_all_channels_sku_inventory b on a.sku_group = b.sku_group and a.ros_hit_date = b.date ), final_check_inwards as ( select *, div0((inventory_on_inward_date-inv),datediff(day,inward_start_date,ros_hit_date)) as ros, (inventory_on_inward_date-inv)/inventory_on_inward_date as str, row_number() over (partition by sku_group order by inward_date asc) as inward_freq from inv_matching a where sku_group not like \'%HANGER%\' and ros >=0 ), max_inwards as ( select sku_group, max(inward_freq) as total_inwards from final_check_inwards group by 1 ), str_check_pre as ( select a.*,b.total_inwards from final_check_inwards a left join max_inwards b on a.sku_group = b.sku_group ), current_inv as ( select sku_group, sum(total_inventory) as current_inv from snitch_db.maplemonk.cut_size_analysis where date = current_date - 1 group by 1 ), str_eligible as ( select a.*, case when a.str < 0.5 then \'no\' else \'yes\' end as str_eligible from str_check_pre a left join current_inv b on a.sku_group = b.sku_group where lower(is_ros_hit) = \'no\' and inward_freq = total_inwards ) select a.*, coalesce(b.str_eligible,\'yes\') as str_eligible from str_check_pre a left join str_eligible b on a.sku_group = b.sku_group and a.inward_date = b.inward_date",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            